def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a, b in history if a == 'D')
    remaining = 100 - n

    if remaining == 2:
        if my_last == 'C' and my_d <= 1 and opp_c >= 95:
            return 'D'
        return 'C'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_c / n > 0.6:
                return 'C'
            return 'D'
        else:
            if opp_c / n > 0.7 and n > 10:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'

    if opp_d / n > 0.3:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    if opp_c / n > 0.85 and n > 20:
        if my_d <= 2:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    return 'C'
